import{f as n,c as i,o as r,aq as t}from"./chunks/framework.D9EfIZ-r.js";const s="/Wahllokalsystem/relationshipOfUIsToElectionProcess.drawio.png",g=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),d={name:"about/index.md"};function a(l,e,h,u,o,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>In diesem Repository wollen wir das Wahllokalsystem der Landeshauptstadt München, das initial zur Bundestagswahl 2017 eingeführt wurde, veröffentlichen. Anlass dafür ist eine geplante Lifecyclemaßnahme. Da wir im Rahmen dieser Maßnahme die gesamte Anwendung betrachten, bot es sich an entsprechend der <a href="https://opensource.muenchen.de/de/principles.html#rechtliche-und-politische-vorgaben" target="_blank" rel="noreferrer">OpenSource-Strategie</a> der Landeshauptstadt München, die Anwendung OpenSource zu stellen.</p><p>Am Ende soll die Anwendung für Interessierte vollständig zur Verfügung stehen.</p><h2 id="was-kann-die-software" tabindex="-1">Was kann die Software <a class="header-anchor" href="#was-kann-die-software" aria-label="Permalink to &quot;Was kann die Software&quot;">​</a></h2><p>Der Hauptfokus der Software liegt auf den Handlungen am Wahltag. Sie unterstützt bei der Eröffnung des Wahllokals, indem man z.B. anhand einer Checkliste prüfen kann, dass alle notwendigen Materialien für die Durchführung vorhanden sind. Während der Zeit der Stimmabgabe wird übermittelt, wie viele Wähler*innen bereits im Wahllokal waren. Des Weiteren werden über die Software wahlrelevante Vorkommnisse dokumentiert.</p><p>Außerdem wird zu definierten Zeitpunkten abgefragt, welche Mitglieder des Wahlvorstandes im Wahllokal anwesend sind. So wird sichergestellt, dass das Gremium zu jeder Zeit ausreichend besetzt ist.</p><p>Während der Stimmauszählung, und der damit verbundenen Erstellung der Niederschrift, unterstützt das System den Wahlvorstand bei der korrekten Erfassung der Daten. Dazu gibt es zahlreiche Regeln und Konsistenzprüfungen, die dem Wahlvorstand Feedback geben, ob die erfassten Daten korrekt sind.</p><p>Das Wahlamt kann über das System den Wahlbezirken wichtige Informationen zukommen lassen.</p><p><img src="'+s+'" alt="Übersicht der Funktionen des Wahllokalsystems im zeitlichen Kontext einer Wahl"><br><em>Übersicht der Funktionen des Wahllokalsystems im zeitlichen Kontext einer Wahl</em></p><h2 id="fachliche-anforderungen" tabindex="-1">Fachliche Anforderungen <a class="header-anchor" href="#fachliche-anforderungen" aria-label="Permalink to &quot;Fachliche Anforderungen&quot;">​</a></h2><p>Im Folgenden werden die fachlichen Anforderungen an die Software je nach Funktion näher beschrieben. Die Einordnung in die Grafik lässt sich der jeweiligen Überschrift &quot;📃 <strong>UseCase: <code>Titel</code></strong>&quot; entnehmen.</p><h3 id="wahllokalsystem-ui" tabindex="-1">Wahllokalsystem UI <a class="header-anchor" href="#wahllokalsystem-ui" aria-label="Permalink to &quot;Wahllokalsystem UI&quot;">​</a></h3><p>Das Wahllokalsystem ist die Anwendung, die am Wahltag vom Wahlvorstand bedient wird.</p><p>📃 <strong>UseCase: <code>Initiales Laden der Daten</code></strong></p><p>In einem ersten Schritt nach dem Login werden die hinterlegten Daten des angemeldeten Benutzerkontos geladen. Kommt es hier zu einem Fehler, wird der Wahlvorstand dazu aufgefordert, sich beim Wahlamt zu melden. Ist der Schritt erfolgreich, müssen anschließend alle für die Wahlen wichtigen Daten ebenfalls erfolgreich geladen werden. Schlägt das Laden fehl, kann die Initialisierungs-Anfrage für die betroffenen Daten wiederholt werden. Bei bestimmten fehlenden Daten wird den Nutzer*innen der Zugriff auf die Anwendung verwehrt, bei anderen, mit niedrigerer Priorität, ist der Zugriff auf die Anwendung trotzdem möglich. Das erfolgreiche Laden ermöglicht später auch eine reibungslose Nutzung im Offline-Modus.</p><p>Folgende Daten werden bei allen Wahlen von beiden Wahlbezirksarten &quot;Urnenwahlbezirk&quot; und &quot;Briefwahlbezirk&quot; geladen: <em>Wahlvorstand</em>, <em>Wahlvorschläge</em>, <em>Kopfdaten</em>, <em>Konfigurationen</em>, <em>Handbuch</em>, <em>Wahlvorbereitung</em>, <em>Eröffnungsuhrzeit</em>, <em>Ereignisse</em>, <em>Druckstatus</em>, <em><a href="./#usecase-stimmen-zaehlen">Stapel der entsprechenden Wahl(en)</a></em>, <em>FortsetzungsUhrzeit</em>, <em>UnterbrechungsUhrzeit</em></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Kommunalwahl-Daten, die nur in einem Urnenwahlbezirk geladen werden</p><p><em>UngültigeWahlscheine</em>, <em>A-Werte</em>, <em>Wählerverzeichnis</em>, <em>Schließungsuhrzeit</em>, <em>Stimmabgabevermerke</em>, <em>Stimmzettel</em>, <em>Begründung - Stimmzettel</em></p></div><div class="info custom-block" data-bwb="true"><p class="custom-block-title">Kommunalwahl-Daten, die nur in einem Briefwahlbezirk geladen werden</p><p><em>Erfasste Wahlbriefe</em>, <em>Zugelassene Wahlbriefe</em>, <em>Wahlscheine</em>, <em>Stimmzettelumschläge</em>, <em>Begründung - Stimmzettelumschläge</em>, <em>Stapel b - leere Stimmzettelumschläge</em></p></div><p>📃 <strong>UseCase: <code>Testdruck durchführen</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Testdruck im Urnenwahlbezirk</p><p>Damit in den Urnenwahllokalen frühzeitig die technischen Geräte auf ihre Funktionalität überprüft werden, werden die Nutzer*innen nach dem initialen Laden der Daten durch einen Dialog dazu aufgefordert, eine Testseite zu drucken. Dieser Dialog kann erst nach erfolgreichem Erscheinen der Druckseite geschlossen werden. Anschließend werden die Nutzer*innen entsprechend der <a href="/Wahllokalsystem/technik/systemspecification/frontend/navigation-and-workflow.html">Navigation</a> zum nächsten Bearbeitungsschritt weitergeleitet.</p></div><p>📃 <strong>UseCase: <code>Erfassung von Ereignissen</code></strong></p><p>Zu jeder Zeit der Wahlhandlung können die Nutzer*innen Ereignisse in der Anwendung erfassen. Jedes Ereignis hat folgende Pflichtfelder:</p><ul><li>eine (berechnete) Ereignisart (siehe Infobox <a href="./#infobox-ereignisse-uwb">&quot;Ereignisse im Urnenwahlbezirk&quot;</a>)</li><li>ein Datum mit Uhrzeit, welches nicht in der Zukunft und nicht vor dem Wahltag liegen darf</li><li>eine aussagekräftige Beschreibung mit mindestens 4 und maximal 500 Zeichen.</li></ul><p>Weiterhin gibt es einige Verhaltensregeln für die Ereigniserfassung:</p><ul><li>Wenn keine Ereignisse vorgefallen sind, muss dies explizit durch das Aktivieren einer Checkbox bestätigt werden, um die Maske speichern zu können.</li><li>Sind Ereignisse eingetreten, müssen diese einzeln erfasst werden.</li><li>Bei Bedarf können eingetragene Ereignisse wieder gelöscht werden.</li><li>Das Löschen aller eingetragenen Ereignisse aktiviert automatisch die Checkboxen &quot;Keine Ereignisse vorgefallen&quot;.</li><li>Das Eintragen neuer Ereignisse, wenn vorher noch keine gespeichert wurden, deaktiviert die Checkboxen automatisch.</li></ul><p>Diese Relationen werden für jeden Wahlbezirk in den Attributen <code>keineVorfaelle</code> und <code>keineVorkommnisse</code> gespeichert, die sich daraus berechnen, ob es Einträge mit der entsprechenden Ereignisart gibt.</p><p id="infobox-ereignisse-uwb"></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Ereignisse im Urnenwahlbezirk</p><p>Im Urnenwahlbezirk wird zwischen Vorfällen, die am Wahltag während oder vor der Stimmabgabe auftreten, und Vorkommnissen, die während der Auszählung auftreten, unterschieden. Vorkommnisse können also auch an einem Tag nach der Wahl auftreten und erfasst werden. Wird die Uhrzeit eines Vorkommnisses nachträglich auf vor der Wahlschließung gesetzt, passt sich auch die Ereignisart des Eintrags entsprechend an und wird zu einem Vorfall, und andersherum. Sobald die Schliessungsuhrzeit gespeichert wird, wird die Ereignisart der Ereignisse ebenfalls neu berechnet. Dementsprechend ist die Ereignisart eng verknüpft mit dem zugehörigen Datum und der Uhrzeit.</p></div><div class="info custom-block" data-bwb="true"><p class="custom-block-title">Ereignisse im Briefwahlbezirk</p><p>Im Briefwahlbezirk werden nur Vorkommnisse erfasst. Dies ist erst möglich, sobald für mindestens eine Wahl eine Wahlurne geöffnet wurde.</p></div><h4 id="vor-der-auszahlung" tabindex="-1">Vor der Auszählung <a class="header-anchor" href="#vor-der-auszahlung" aria-label="Permalink to &quot;Vor der Auszählung&quot;">​</a></h4><h5 id="vor-der-stimmabgabe" tabindex="-1">Vor der Stimmabgabe <a class="header-anchor" href="#vor-der-stimmabgabe" aria-label="Permalink to &quot;Vor der Stimmabgabe&quot;">​</a></h5><p>📃 <strong>UseCase: <code>Erfassung der Anwesenheit des Wahlvorstands</code></strong></p><p>Beim Start der Anwendung wurden alle Wahlvorstandsmitglieder geladen, die für diesen Tag im Wahlbezirk eingeteilt sind. Die Liste der Wahlvorstandsmitglieder ist nach Funktion in folgender Reihenfolge sortiert:</p><ol><li>Wahlvorsteher*in</li><li>Stellvertretung Wahlvorsteher*in</li><li>Schriftführer*in</li><li>Stellvertretung Schriftführer*in</li><li>Beisitzer*in</li></ol><p>Bei gleicher Funktion wird zusätzlich nach Familienname und Vorname sortiert.</p><p>Für alle Mitglieder, die tatsächlich anwesend sind, muss die Anwesenheit manuell per Checkbox erfasst werden. Die Anwesenheit kann nur bei Erfüllung folgender Bedingungen gespeichert werden:</p><ul><li>es muss mindestens ein/e Wahlvorsteher*in oder dessen/deren Stellvertretung anwesend sein</li><li>es muss mindestens ein/e Schriftführer*in oder dessen/deren Stellvertretung anwesend sein</li><li>vor der Wahlschließung müssen mindestens 3 Mitglieder anwesend sein</li><li>nach der Wahlschließung müssen mindestens 5 Mitglieder anwesend sein</li></ul><p>Die Nutzer*innen der Anwendung werden durch eine Fehlermeldung darauf hingewiesen, wenn diese Bedingungen nicht erfüllt sind. Über einen &quot;Aktualisieren&quot;-Button, welcher den Wahlvorstand mit einem <code>forceUpdate</code>-Flag neu lädt, können die Nutzer*innen erzwingen, die Mitglieder durch eine mögliche neue Zusammensetzung zu überschreiben.</p><div class="info custom-block" data-bwb="true"><p class="custom-block-title">📃 UseCase: <code>Druck einer Wahlvorstand-Nachbesetzung</code> im Briefwahlbezirk</p><p>In manchen Fällen ist es in einem Briefwahlbezirk notwendig, eine Nachbesetzung zu organisieren. Hierzu können die Nutzer*innen über den Button <code>Nachbesetzung drucken</code> ein entsprechendes PDF-Dokument generieren lassen, welches im Anschluss gedruckt und ausgefüllt werden kann.</p></div><p>📃 <strong>UseCase: <code>Vorbereitung der Wahlhandlung - Prüfung der Ausstattung des Wahllokals</code></strong></p><p>Für jede an dem entsprechenden Tag stattfindende Wahl muss die Anzahl der zur Verfügung gestellten Wahlurnen erfasst werden. Die Nutzer*innen müssen bestätigen, dass die Wahlurnen vor der Nutzung leer waren und versiegelt wurden, um speichern zu können.</p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Abstimmungsschutzvorrichtungen im Urnenwahlbezirk</p><p>In jedem Urnenwahllokal müssen gewisse Abstimmungsschutzvorrichtungen gewährleistet sein, um das Wahlgeheimnis nicht zu gefährden. Dementsprechend muss die Summe der Anzahl der Tische mit Sichtblenden, der Nebenräume im Wahlraum, sowie der Wahlkabinen insgesamt mindestens 1 ergeben, bevor die Nutzer*innen speichern können.</p></div><p>📃 <strong>UseCase: <code>Vorbereitung der Wahlhandlung - Auf ungültige Wahlscheine hinweisen</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Pflege des Wählerverzeichnisses im Urnenwahlbezirk</p><p>Vor der Stimmabgabe muss sichergestellt werden, dass das Wählerverzeichnis aktuell und korrekt ist. Dazu müssen nachträglich erteilte Wahlscheine berücksichtigt werden, um die Integrität der Wahl zu gewährleisten und allen<br> wahlberechtigten Personen die Möglichkeit zu bieten, ihre Stimmen abzugeben. Es muss immer mindestens die Option ausgewählt werden, mit welcher bestätigt wird, dass der Wahlvorstand über ungültige Wahlscheine unterrichtet wurde. Der Wahlvorstand wird vom Wahlamt darüber benachrichtigt, ob weitere Korrekturen am Wählerverzeichnis und der zugehörigen Ansicht in der Anwendung vorzunehmen sind.</p></div><p>📃 <strong>UseCase: <code>Wahl eröffnen</code></strong></p><p>Die Nutzer*innen werden dazu aufgefordert, die Uhrzeit einzutragen, zu welcher die Stimmabgabe begonnen wurde, beziehungsweise zu welcher der Wahlvorstand zusammengetreten ist. Um speichern zu können, dürfen die Nutzer*innen keine Zeit eingeben, die in der Zukunft liegt. Außerdem müssen die folgenden Grenzwerte je nach Wahlbezirksart berücksichtigt werden:</p><div class="info custom-block" data-uwb="true"><p class="custom-block-title"><code>Erfassung der Öffnung des Wahllokals</code> im Urnenwahlbezirk</p><p>Die früheste Zeit, zu der das Wahllokal geöffnet werden kann, ist der Standardwert von 8 Uhr und wird mit dem Konfigurationsparameter <code>FRUEHESTE_EROEFFNUNGSUHRZEIT_UW</code> geladen. Die späteste Zeit zur Öffnung richtet sich nach dem Konfigurationsparameter <code>FRUEHESTE_SCHLIESSUNGSUHRZEIT_UW</code> mit einem Standardwert von 18 Uhr.</p></div><div class="info custom-block" data-bwb="true"><p class="custom-block-title"><code>Erfassung des Zusammentretens des Wahlvorstands</code> im Briefwahlbezirk</p><p>Die früheste Zeit, zu welcher der Wahlvorstand zusammentreten kann, ist der Standardwert von 15 Uhr und wird mit dem Konfigurationsparameter <code>FRUEHESTE_EROEFFNUNGSUHRZEIT_BW</code> geladen.</p></div><p>📃 <strong>UseCase: <code>Erfassung der erhaltenen Wahlbriefe</code></strong></p><div class="info custom-block" data-bwb="true"><p class="custom-block-title">Briefwahlbezirk</p><p>In einem Briefwahlbezirk werden die erhaltenen Wahlbriefe erfasst. Die dabei relevanten Werte sind die Anzahl der Wahlbriefe, die vor 18 Uhr übergeben wurden. Dabei muss mindestens ein Wahlbrief erfasst werden. Ebenso gilt es die Anzahl der Verzeichnisse der für ungültig erklärten Wahlscheine sowie die Anzahl der Nachträge zu den Verzeichnissen zu erfassen. Erst nach der Angabe dieser drei Werte können die Informationen gespeichert werden. Optional ist die Angabe einer Anzahl an nachgelieferten Wahlbriefen nach 18 Uhr. Sollte es nachgelieferte Wahlbriefe geben, so muss eine Uhrzeit dazu angegeben werden.</p></div><h5 id="wahrend-der-stimmabgabe" tabindex="-1">Während der Stimmabgabe <a class="header-anchor" href="#wahrend-der-stimmabgabe" aria-label="Permalink to &quot;Während der Stimmabgabe&quot;">​</a></h5><p>📃 <strong>UseCase: <code>Erfassung der absoluten Wahlbeteiligung</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Urnenwahlbezirk</p><p>In einem Urnenwahlbezirk kann nach der Öffnung der Wahl die Anzahl der Wähler*innen, die das Wahllokal besuchen, erfasst werden. Jedes Mal, wenn die Nutzer*innen auf den entsprechenden Button klicken, wird die Wähler*innenanzahl um 1 erhöht. Alternativ können die Nutzer*innen das Feld über seine Tastatur steuern. Wenn sie sich nicht in einem Input-Feld befinden, können sie die Taste <code>+</code> drücken, oder, wenn der Zählbutton fokussiert ist, die Tasten <code>Eingabe</code> oder <code>Leertaste</code>.</p></div><p>📃 <strong>UseCase: <code>Aktualisieren der Anwesenheit des Wahlvorstandes</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">nur im Urnenwahlbezirk</p><p>Mit dem Schichtwechsel im Urnenwahlbezirk müssen die Anwesenheiten der neuen Schicht erfasst werden. Der Wahlvorstand wird beim Erreichen der Uhrzeit des Schichtwechsels über einen Dialog darüber informiert. Über den Dialog kann direkt zur entsprechenden Seite navigiert werden. Die Uhrzeit für den Dialog wird über den Konfigurationsparameter <code>MELDUNGSZEIT_ANWESENHEIT_CHECK</code> gesteuert.</p></div><p>📃 <strong>UseCase: <code>Wahl schliessen</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title"><code>Erfassung der Schließung des Wahllokals</code> im Urnenwahlbezirk</p><p>Analog zur Öffnung der Wahl, wird sie vor der Auszählung auch wieder geschlossen. Die früheste Zeit zur Schließung richtet sich nach dem Konfigurationsparameter <code>FRUEHESTE_SCHLIESSUNGSUHRZEIT_UW</code> mit einem Standardwert von 18 Uhr. Auch diese darf nicht in der Zukunft liegen.</p></div><div class="info custom-block" data-bwb="true"><p class="custom-block-title">Briefwahlbezirk</p><p>Im Briefwahlbezirk gibt es keine &quot;Schließung&quot; des Wahllokals. Es wird aber eine Uhrzeit mit dem UseCase <code>Erfassung abgegebener Stimmen</code> übermittelt, welche der Schliessungsuhrzeit im Urnenwahllokal gleicht. Die früheste Zeit, die übermittelt werden kann richtet sich nach dem Konfigurationsparameter <code>FRUEHESTE_SCHLIESSUNGSUHRZEIT_BW</code> mit einem Standardwert von 18 Uhr.</p></div><p>📃 <strong>UseCase: <code>Überprüfung der ungültigen Wahlscheine</code></strong></p><div class="info custom-block" data-uwb="true"><p class="custom-block-title">Urnenwahlbezirk</p><p>In einem Urnenwahlbezirk muss, wenn jemand mit Wahlschein kommt, geprüft werden, ob dieser Wahlschein gültig ist. Dazu gibt es in der Anwendung eine Liste ungültiger Wahlscheine. Die Nutzer*innen geben die Nummer des Wahlscheins ein und suchen. Nach der Suche erhalten die Nutzer*innen Feedback darüber, ob der Wahlschein gültig oder ungültig ist. Entsprechend werden auch Handlungsanweisungen angezeigt. Ist der Wahlschein ungültig, werden in der Fehlermeldung neben der Wahlscheinnummer auch Vor- und Familienname angezeigt. Außerdem werden die Nutzer*innen in diesem Fall dazu aufgefordert, den Beschluss über die Zurückweisung als Ereignis zu erfassen.</p><p>Um suchen zu können, muss eine Wahlscheinnummer vorhanden sein. Die Wahlscheinnummer muss außerdem im Bereich von <code>1</code> bis <code>9999999</code> liegen.</p><p>Nach einer Suche kann über den Button, der zuvor die Suche ausgeführt hat, die Suche zurückgesetzt werden. Dabei werden die Eingabe und Handlungsanweisungen entfernt. Die Suche wird ebenfalls zurückgesetzt, wenn die Nutzer*innen die Wahlscheinnummer verändern.</p><p>Zur Unterstützung des Wahlvorstands wird ein Bild angezeigt, das helfen soll, die Stelle, wo die Wahlnummer steht, zu identifizieren.</p><p>Die vorhandene Liste kann über den Aktualisieren-Button erneut geladen werden.</p><p>Ist die Liste leer oder konnte die Liste nicht geladen werden, erhalten die Nutzer*innen entsprechende Fehlermeldungen angezeigt.</p></div><p>📃 <strong>UseCase: <code>Beschluss zu uneindeutigen Wahlbriefen erfassen</code></strong></p><div class="info custom-block" data-bwb="true"><p class="custom-block-title">Briefwahlbezirk</p><p>Der Wahlvorstand kann über jeden bedenklichen Wahlbrief einen individuellen Beschluss fassen. Dabei wird zwischen der Gültigkeit des gesamten Wahlscheins und anschließend der einzelnen Stimmzettelumschläge unterschieden. Ein Wahlschein kann die Werte <code>Zugelassen</code>, <code>Wahlschein ungültig laut Liste</code>, <code>Kein Original-Wahlschein</code>, oder <code>Unterschrift auf Wahlschein fehlt</code> haben. Für die Stimmzettelumschläge gibt es die Zurückweisungsgründe <code>Zugelassen</code>, <code>Stimmzettelumschlag fehlt</code>, <code>Lose Stimmzettel</code>, <code>Wahlbrief und Stimmzettelumschlag offen</code>, <code>Wahlscheine ungleich Stimmzettelumschläge</code>, <code>Nicht-amtlicher Stimmzettelumschlag</code>, <code>Stimmzettelumschlag gefährdet Wahlgeheimnis</code>, <code>Gegenstand im Stimmzettelumschlag</code> oder <code>Für diese Wahl nicht wahlberechtigt</code>.</p><p>Es muss immer zuerst der Beschluss für den gesamten Wahlschein gefasst werden. Ist der Wahlschein nicht <code>Zugelassen</code>, bekommen die Stimmzettelumschläge der einzelnen Wahlen den gleichen Zurückweisungsgrund. Ist der Wahlschein <code>Zugelassen</code>, wird der im Anschluss gewählte Stimmzettelumschlag-Zurückweisungsgrund auf die anderen Wahlen übertragen. Der einzige Beschluss, der unabhängig für eine Wahl gefasst werden kann, ohne dass die anderen Wahlen den gleichen Zurückweisungsgrund erhalten, ist <code>Für diese Wahl nicht Wahlberechtigt</code>.</p><p>Der Wahlvorstand kann die Daten der Eingabemaske nur speichern, wenn für alle Wahlscheine und Stimmzettelumschläge ein valider Wert eingetragen wurde.</p></div><h5 id="wahrend-der-auszahlung" tabindex="-1">Während der Auszählung <a class="header-anchor" href="#wahrend-der-auszahlung" aria-label="Permalink to &quot;Während der Auszählung&quot;">​</a></h5><p>📃 <strong>UseCase: <code>Erfassung abgegebener Stimmen</code></strong></p><p>Im Urnenwahl- sowie im Briefwahlbezirk kann der Wahlvorstand die Anzahl der abgegebenen Stimmen erfassen. Die Erfassung erfolgt für jede Wahl einzeln.</p><div class="info custom-block" data-uwb="true"><p class="custom-block-title"><code>Zählen der Stimmzettel</code> im Urnenwahlbezirk</p><p>Der Wahlvorstand wird dazu aufgefordert, die Anzahl der erhaltenen Stimmzettel zu zählen und zu erfassen.</p></div><div class="info custom-block" data-bwb="true"><p class="custom-block-title"><code>Zählen der Stimmzettelumschläge</code> im Briefwahlbezirk</p><p>Der Wahlvorstand wird dazu aufgefordert, die Anzahl der erhaltenen Stimmzettelumschläge zu zählen und zu erfassen. Außerdem muss eine Uhrzeit mit erfasst werden, zu welcher die Wahlurne geöffnet wurde. Diese Uhrzeit darf nicht in der Zukunft liegen und muss größer oder gleich der frühesten Schließungsuhrzeit sein (Konfiguration <code>FRUEHESTE_SCHLIESSUNGSUHRZEIT_BW</code>, Standardwert 18:00).</p></div><p id="usecase-stimmen-zaehlen"></p><p>📃 <strong>UseCase: <code>Stimmzettel auswerten und Stimmen zählen</code></strong></p><p>Für jede Wahl gibt es ein bestimmtes Zählverfahren, in welchem die Stimmzettel nach verschiedenen Stapeln sortiert und anschließend ausgezählt werden.</p><p>Stapel für die <strong>Oberbürgermeisterwahl</strong>:</p><table tabindex="0"><thead><tr><th>Stapel</th><th>Beschreibung</th><th>Anmerkung</th></tr></thead><tbody><tr><td><code>A</code></td><td>Zweifelsfrei gültige Stimmen</td><td></td></tr><tr><td><code>B_Leer</code></td><td>Zweifelsfrei ungültige Stimmen: Leere Stimmzettelumschläge</td><td>nur BWB</td></tr><tr><td><code>B_Ungekennzeichnet</code></td><td>Zweifelsfrei ungültige Stimmen: Ungekennzeichnete Stimmzettel</td><td></td></tr><tr><td><code>C_Gueltig</code></td><td>Bedenkliche Stimmzettel, die für gültig erklärt wurden</td><td></td></tr><tr><td><code>C_Ungueltig</code></td><td>Bedenkliche Stimmzettel, die für ungültig erklärt wurden</td><td></td></tr></tbody></table><p>Stapel für die <strong>Migrationsbeiratswahl</strong>:</p><table tabindex="0"><thead><tr><th>Stapel</th><th>Beschreibung</th><th>Anmerkung</th></tr></thead><tbody><tr><td><code>A</code></td><td>Zweifelsfrei gültige Stimmen: unverändert</td><td>mit Listenkreuz</td></tr><tr><td><code>B</code></td><td>Zweifelsfrei gültige Stimmen: verändert, nur ein Wahlvorschlag</td><td>mit oder ohne Listenkreuz</td></tr><tr><td><code>B_C</code></td><td>Zweifelsfrei gültige Stimmen: verändert, mehrere Wahlvorschläge</td><td>Kandidat*innenstimmen</td></tr><tr><td><code>D_Ungueltig</code></td><td>Leere und ungekennzeichnete Stimmzettel</td><td></td></tr></tbody></table><h4 id="nach-der-auszahlung" tabindex="-1">Nach der Auszählung <a class="header-anchor" href="#nach-der-auszahlung" aria-label="Permalink to &quot;Nach der Auszählung&quot;">​</a></h4><p>📃 <strong>UseCase: <code>Kontrolle, Übermittlung und Druck der Schnellmeldung</code></strong></p><p>Im Urnenwahl - sowie im Briefwahlbezirk wird von der Schriftführung eine Schnellmeldung zu den vorläufigen Ergebnissen nach der Auszählung der Stimmen erstellt.</p><p>Die Schnellmeldung wird automatisch erstellt, kann dann korrigiert und versendet sowie gedruckt werden.</p><p>📃 <strong>UseCase: <code>Kontrolle, Übermittlung und Druck der Niederschrift</code></strong></p><p>Im Urnenwahl - sowie im Briefwahlbezirk wird von der Schriftführung eine Wahlniederschrift über die Wahlhandlung sowie die Ermittlung und Feststellung des Wahlergebnisses erstellt.</p><p>Die Niederschrift wird automatisch erstellt, kann dann korrigiert und versendet sowie gedruckt werden.</p>',81)])])}const b=n(d,[["render",a]]);export{g as __pageData,b as default};
